struct Circle    { double r; };
struct Rectangle { double w, h; };

using Shape = std::variant<Circle, Rectangle>;

double area(const Shape& s) {
  return std::visit(overloaded{
      [](const Circle& c)    { return std::numbers::pi * c.r * c.r; },
      [](const Rectangle& r) { return r.w * r.h; },
  }, s);   // a missing alternative -> visitor not callable -> compile error
}

struct area_visitor : boost::static_visitor<double> {
  double operator()(const Circle& c) const    { return pi * c.r * c.r; }
  double operator()(const Rectangle& r) const { return r.w * r.h; }
  // missing an overload => the StaticVisitor requirements are not met => error
};

boost::variant<Circle, Rectangle> shape = Circle{2.0};
double a = boost::apply_visitor(area_visitor{}, shape);

struct Visitor {                                 // one pure virtual per variant
  virtual void visit(const Circle&) = 0;
  virtual void visit(const Rect&)   = 0;
};
struct Shape { virtual void accept(Visitor&) const = 0; virtual ~Shape() = default; };
struct Circle : Shape { double r;    void accept(Visitor& v) const override; };
struct Rect   : Shape { double w, h; void accept(Visitor& v) const override; };
struct AreaVisitor : Visitor {
  double area = 0;
  void visit(const Circle& c) override { area = pi * c.r * c.r; }
  void visit(const Rect& r) override   { area = r.w * r.h; }
  // omitting one overload leaves AreaVisitor abstract -> compile error
};
